-- The built-in content of the eight modes moves out of the code and into ContentItem.
--
-- 1. `original` keeps every built-in element as it was first defined, so Reset / Restore in the Admin panel need no code.
-- 2. The built-in elements are loaded here (the data below is the content that used to live in src/<mode>/<mode>.catalog.ts).
--    Rows that already exist (inserted by the previous version on startup, or copied from the older tables) are never changed,
--    so edits and deletes made in the Admin panel survive; they only get their `original`, their position and their unit title.

-- AlterTable
ALTER TABLE "ContentItem" ADD COLUMN "original" JSONB;

-- Staging table for the built-in content (dropped at the end)
CREATE TABLE "_content_seed" (
    "mode" TEXT NOT NULL,
    "itemId" TEXT NOT NULL,
    "position" INTEGER NOT NULL,
    "data" JSONB NOT NULL
);


-- Built-in elements the table does not have yet
SELECT md5(random()::text || clock_timestamp()::text || s."mode" || s."itemId"), s."mode", s."itemId", s."position", s."data", s."data", true, false, false, CURRENT_TIMESTAMP
FROM "_content_seed" s
ON CONFLICT ("mode", "itemId") DO NOTHING;

-- Built-in rows that already exist: remember the original; fill a missing position and a missing unit title (same unit only)
UPDATE "ContentItem" c
SET "original" = s."data",
    "position" = COALESCE(c."position", s."position"),
    "data" = CASE
      WHEN c."data"->'unitTitle' IS NULL AND s."data"->'unitTitle' IS NOT NULL AND (c."data"->>'unit') = (s."data"->>'unit')
      THEN c."data" || jsonb_build_object('unitTitle', s."data"->'unitTitle')
      ELSE c."data"
    END
FROM "_content_seed" s
WHERE c."mode" = s."mode" AND c."itemId" = s."itemId" AND c."seeded" = true;

-- DropTable
DROP TABLE "_content_seed";
